export const DATA_BIAS_FAIRNESS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Data berasal dari suatu tempat",q:"Data yang dipakai melatih AI...",options:["Dikumpulkan oleh orang, dari sumber tertentu, pada waktu tertentu — pilihan ini memengaruhi isinya","Mewakili seluruh penduduk dunia dengan adil; data dikumpulkan secara otomatis tanpa pilihan manusia","Muncul dengan sendirinya dari alam dan bersifat netral, tanpa dipengaruhi pengumpulnya"],answer:0,explain:"Setiap kumpulan data adalah hasil pilihan: apa yang dikumpulkan, dari siapa, kapan, dan apa yang ditinggalkan.",hint:"Siapa yang mengumpulkan data, dan dari mana?"},
{n:2,type:"mcq",micro:"Keterwakilan (representasi)",q:"Data 'mewakili' sebuah kelompok kalau...",options:["Jumlah contohnya sangat besar, walaupun sebagian besar berasal dari kelompok lain yang berbeda","Berisi contoh dari seluruh bagian kelompok itu dengan proporsi yang mirip kenyataannya","Berisi banyak contoh dari satu bagian kelompok saja yang paling mudah dikumpulkan"],answer:1,explain:"Keterwakilan bukan soal jumlah total, melainkan apakah semua bagian kelompok muncul dengan porsi yang wajar.",hint:"Kalau survei kelas hanya diisi anak barisan depan, apakah itu mewakili seluruh kelas?"},
{n:3,type:"mcq",micro:"Bias masuk, bias keluar",q:"'Bias masuk, bias keluar' berarti...",options:["Model memperbaiki sendiri bias di dalam datanya, jadi data yang berat sebelah tidak menjadi masalah bagi hasilnya","Data latih tidak berpengaruh pada model; hasilnya hanya ditentukan oleh kecepatan komputernya","Kalau data latihnya berat sebelah atau tidak adil, model yang dihasilkan cenderung berat sebelah juga"],answer:2,explain:"Model belajar pola dari data. Kalau polanya mengandung ketidakadilan, model menirunya.",hint:"Kalau kamu belajar dari buku yang keliru, apa yang kamu pelajari?"},
{n:4,type:"mcq",micro:"Contoh bias keterwakilan",q:"AI pengenal suara dilatih terutama dari suara orang dewasa. Kemungkinan besar ia bekerja buruk untuk...",options:["Suara anak-anak dan lansia yang jarang ada di data latih","Orang dewasa yang suaranya paling banyak ada di data pelatihan","Penyiar radio yang bicara jelas dan lantang di studio"],answer:0,explain:"Kelompok yang kurang terwakili dalam data latih sering mendapat layanan yang lebih buruk.",hint:"Siapa yang jarang muncul dalam data latih?"},
{n:5,type:"mcq",micro:"Data historis membawa ketidakadilan lama",q:"Model dilatih dari keputusan peminjaman bank 20 tahun lalu, saat kelompok tertentu sering ditolak tanpa alasan wajar. Model itu...",options:["Mengabaikan data lama dan hanya meniru keputusan yang dinilai wajar saja","Bisa mempelajari & mengulang pola penolakan yang tidak adil itu","Membuat keputusan yang adil; komputer tidak punya prasangka"],answer:1,explain:"Data historis merekam praktik masa lalu, termasuk yang tidak adil. Model bisa 'membekukan' ketidakadilan itu ke masa depan.",hint:"Pola apa yang terekam dalam keputusan 20 tahun lalu?"},
{n:6,type:"order",micro:"Bagaimana bias data menjadi bias model",q:"Urutkan bagaimana bias berpindah dari dunia ke model.",items:["Dunia nyata punya ketimpangan (kelompok tertentu kurang kesempatan)","Data yang dikumpulkan mencerminkan ketimpangan itu","Model belajar pola dari data tersebut","Model membuat prediksi yang mengulang, kadang memperkuat, pola itu"],answer:[0,1,2,3],explain:"Ketimpangan dunia → terekam di data → dipelajari model → keluar sebagai prediksi yang berat sebelah.",hint:"Mulai dari kenyataan sebelum data dikumpulkan."},
{n:7,type:"mcq",micro:"Bias bukan berarti niat jahat",q:"Bias dalam sistem AI...",options:["Hanya muncul bila pembuatnya rasis atau berniat jahat; data dan dunia tempat data dikumpulkan dianggap tidak punya sumber bias lain sama sekali","Hanyalah khayalan; program komputer hanya menghitung angka dan tidak dapat memengaruhi keadilan bagi orang yang dikenainya","Sering muncul tanpa ada yang berniat jahat — dari data yang tidak lengkap, pilihan yang tidak disadari, atau dunia yang memang timpang"],answer:2,explain:"Kebanyakan bias AI tidak disengaja. Karena itu penting sengaja memeriksanya, bukan menganggapnya mustahil.",hint:"Bisakah sesuatu jadi tidak adil tanpa ada yang bermaksud begitu?"},
{n:8,type:"mcq",micro:"Siapa yang mengumpulkan label",q:"Label 'komentar ini kasar / sopan' pada data latih diberikan oleh orang. Kalau semua pemberi label dari satu latar belakang...",options:["Definisi mereka tentang 'kasar' bisa menyerap bias latar itu, dan model mewarisinya","Label menjadi objektif; kelompok yang seragam dianggap lebih mudah bersepakat soal kata kasar","Tidak berpengaruh pada model; yang dipelajari hanya jumlah komentar dan bukan labelnya"],answer:0,explain:"Label mencerminkan penilaian pemberinya. Pemberi label yang beragam menghasilkan label yang lebih seimbang.",hint:"Apakah dua orang dari budaya berbeda selalu sepakat apa yang 'kasar'?"},
{n:9,type:"mcq",micro:"Data hilang / tidak tercatat",q:"Kalau sebuah kelompok jarang memakai layanan digital, datanya jarang tercatat. Akibatnya untuk AI...",options:["Model menjadi lebih netral; data kelompok itu dianggap tidak memengaruhi hasilnya","Kelompok itu 'tak terlihat' oleh model, dan model kurang bisa melayani mereka","Model otomatis mencari mereka di tempat lain dan layanannya tetap setara"],answer:1,explain:"Data yang tidak ada juga sebuah bias: kelompok yang tidak terekam tidak diperhitungkan.",hint:"Kalau kamu tidak ada dalam data, bisakah model belajar tentangmu?"},
{n:10,type:"mcq",micro:"Keadilan: perlakuan yang setara",q:"Salah satu makna 'adil' untuk sistem AI adalah...",options:["Setiap orang mendapat hasil yang diinginkannya, tidak peduli situasi atau kebutuhan masing-masing","Kelompok yang datanya paling banyak menang; model lebih mengenali mereka daripada kelompok kecil","Dua orang dengan situasi yang pada dasarnya sama mendapat hasil yang sama, terlepas dari kelompok mereka"],answer:2,explain:"Keadilan sering berarti: faktor yang seharusnya tidak relevan (kelompok) tidak mengubah hasil untuk orang dengan situasi serupa.",hint:"Haruskah dua pelamar dengan nilai & pengalaman sama mendapat penilaian berbeda karena kelompoknya?"},
{n:11,type:"tf",micro:"Menghapus 'kelompok' dari data tidak otomatis adil",q:"Benar atau Salah: Menghapus kolom seperti 'jenis kelamin' dari data tidak menjamin model jadi adil, karena model bisa menebaknya dari kolom lain (nama, hobi, pilihan kata).",answer:true,explain:"Informasi kelompok sering 'bocor' lewat variabel lain yang berkorelasi. Keadilan butuh pemeriksaan hasil, bukan hanya menyembunyikan label.",hint:"Bisakah kamu menebak banyak hal tentang seseorang tanpa bertanya langsung?"},
{n:12,type:"mcq",micro:"Contoh nyata: pengenalan wajah",q:"Beberapa sistem pengenalan wajah dulu jauh lebih akurat untuk wajah berkulit terang daripada gelap. Penyebab paling mungkin:",options:["Data latih berisi jauh lebih banyak wajah berkulit terang","Wajah berkulit gelap 'lebih sulit' secara alami","Kebetulan"],answer:0,explain:"Ketimpangan keterwakilan dalam data latih menghasilkan ketimpangan akurasi. Data yang diseimbangkan memperbaikinya.",hint:"Wajah jenis apa yang lebih banyak di data latih?"},
{n:13,type:"mcq",micro:"Dampak berbeda pada kelompok berbeda",q:"Model yang 'akurat 90% secara keseluruhan' bisa jadi...",options:["95% akurat untuk setiap kelompok, dan angka total menggambarkan seluruh pengguna sama baiknya","95% akurat untuk mayoritas dan 60% untuk minoritas — angka total menyembunyikan ketimpangan","Adil bagi seluruh kelompok; akurasi total tinggi dianggap menjamin tak ada yang dirugikan"],answer:1,explain:"Rata-rata bisa menutupi kesenjangan. Memeriksa kinerja per kelompok mengungkapnya.",hint:"Bisakah rata-rata satu kelas bagus meski sebagian siswa nilainya sangat rendah?"},
{n:14,type:"mcq",micro:"Bias memengaruhi hidup nyata",q:"Kalau model seleksi pekerjaan bias, akibatnya...",options:["Hanya angka di layar komputer yang berubah, sedangkan kehidupan nyata orang tidak terpengaruh oleh hasilnya","Tidak ada orang yang terpengaruh; keputusan model hanyalah saran yang jarang dipakai dalam kenyataan","Orang dari kelompok tertentu kehilangan kesempatan kerja secara sistematis — dampak nyata pada hidup mereka"],answer:2,explain:"Bias AI bukan masalah teknis abstrak; ia menentukan siapa yang dapat pinjaman, pekerjaan, beasiswa, atau perhatian medis.",hint:"Apa yang terjadi pada orang yang terus ditolak oleh sistem?"},
{n:15,type:"tf",micro:"Data lebih banyak bukan solusi otomatis",q:"Benar atau Salah: Cara paling andal memperbaiki keadilan model adalah menambah lebih banyak data, meskipun data tambahan itu punya bias yang sama.",answer:false,explain:"10× data bias = model tetap bias, hanya lebih 'percaya diri'. Yang dibutuhkan adalah data yang lebih representatif, bukan sekadar lebih banyak.",hint:"Kalau semua data tambahan dari kelompok yang sudah dominan, siapa yang jadi lebih terwakili?"},
{n:16,type:"mcq",micro:"Mengenali bias sebelum menerapkan",q:"Sebelum sekolah memakai 'AI penilai esai', langkah bijak:",options:["Uji pada esai dari beragam kelompok siswa & bandingkan skornya dengan penilaian guru — periksa apakah ada kelompok yang dirugikan","Langsung pakai saja; 'AI itu objektif' dan menilai semua siswa dengan cara yang sama tanpa perlu diuji dulu oleh pihak sekolah mana pun","Percaya penuh pada klaim penjualnya bahwa produk itu adil, tanpa menguji atau membandingkannya dengan penilaian guru di sekolah"],answer:0,explain:"Menguji keadilan sebelum penerapan mencegah kerugian yang sulit diperbaiki nanti.",hint:"Bagaimana kamu tahu alat itu adil sebelum mengandalkannya?"},
{n:17,type:"mcq",micro:"Umpan balik memperkuat bias",q:"Polisi lebih sering patroli di area A (karena data lama menunjukkan lebih banyak laporan), lalu menemukan lebih banyak pelanggaran di sana (karena lebih banyak yang mengawasi), lalu data 'membuktikan' area A lebih rawan. Ini...",options:["Kebetulan statistik; data kejahatan dicatat acak tiap bulan di semua area","Lingkaran umpan balik yang memperkuat bias awal, bukan cerminan kenyataan yang objektif","Bukti bahwa area A memang paling rawan; angka laporannya paling tinggi dibanding area lain"],answer:1,explain:"Sistem yang keputusannya memengaruhi data berikutnya bisa terjebak memperkuat bias awalnya sendiri.",hint:"Kalau kamu hanya mencari di satu tempat, di mana kamu akan menemukan sesuatu?"},
{n:18,type:"mcq",micro:"Siapa yang mendefinisikan 'adil'",q:"Menentukan apa arti 'adil' untuk sebuah sistem...",options:["Bisa dihitung secara otomatis oleh komputer, dan pembuat teknis cukup menjalankan rumusnya tiap bulan tanpa melibatkan pihak lain","Tidak perlu dibahas; model yang akurat dengan sendirinya sudah adil bagi seluruh kelompok pengguna","Adalah keputusan nilai yang sebaiknya melibatkan orang-orang yang terdampak, bukan hanya pembuat teknisnya"],answer:2,explain:"Ada beberapa definisi keadilan yang bisa saling bertentangan. Memilih yang mana adalah pilihan manusia yang harus dibahas terbuka.",hint:"Siapa yang paling tahu apakah sebuah keputusan terasa adil?"},
{n:19,type:"mcq",micro:"Bias dalam pengumpulan data",q:"Survei kepuasan aplikasi hanya bisa diisi lewat aplikasi itu sendiri. Bias yang muncul:",options:["Orang yang sudah berhenti memakai aplikasi (mungkin karena tidak puas) tidak terwakili","Survei menjadi lebih akurat karena hanya pengguna aktif yang mengisinya dengan sungguh-sungguh","Tidak ada bias karena semua pengguna aktif memiliki kesempatan yang sama untuk menjawab"],answer:0,explain:"Cara data dikumpulkan bisa menyaring keluar suara-suara tertentu — di sini, pengguna yang paling tidak puas.",hint:"Siapa yang tidak bisa mengisi survei ini, dan apa pendapat mereka mungkin?"},
{n:20,type:"open",micro:"Menemukan bias dalam sebuah data",q:"Sebuah tim mengumpulkan foto 'ruang kelas yang rapi' untuk melatih AI, dengan memotret 20 kelas di satu sekolah swasta perkotaan yang fasilitasnya lengkap. Jelaskan minimal 3 cara data ini bisa bias, dan bagaimana memperbaikinya.",explain:"Jawaban baik mengenali bias sumber tunggal, sampel kecil, waktu, dan label subjektif, lalu mengusulkan keragaman sumber + kriteria label yang jelas & pelabel yang beragam.",hint:"Tanya: sekolah seperti apa yang TIDAK ada di data ini, dan apa yang model jadi tidak tahu?",sample:"(1) Hanya satu sekolah & satu jenis (swasta, kota, fasilitas lengkap) → model belajar 'rapi' = ruangan dengan perabot bagus & lengkap; kelas sederhana yang bersih tapi minim perabot bisa dinilai 'tidak rapi'. (2) Hanya 20 kelas → variasi terbatas (tata letak, ukuran, jenis bangku). (3) Mungkin difoto pada waktu tertentu (pagi sebelum siswa datang) → tidak mewakili kondisi sepanjang hari. (4) 'Rapi' didefinisikan oleh tim pemotret saja — bisa mencerminkan selera mereka. Perbaikan: kumpulkan foto dari banyak sekolah berbeda (negeri/swasta, kota/desa, fasilitas beragam), berbagai waktu, dan minta beberapa orang dengan latar berbeda ikut melabeli 'rapi/tidak rapi' dengan kriteria yang disepakati (mis. lantai bersih, barang tertata, jalan tidak terhalang) — bukan sekadar 'terlihat mewah'."},
{n:21,type:"classify",micro:"Jenis bias data",q:"Kelompokkan tiap situasi ke jenis biasnya: 'Bias keterwakilan (kelompok kurang muncul)', 'Bias historis (data merekam ketidakadilan lama)', atau 'Bias pengukuran (cara data dikumpulkan/dilabeli timpang)'.",items:["Data suara 90% dari satu negara berbahasa Inggris","Data promosi jabatan dari era ketika perempuan jarang dipromosikan","Label 'berprestasi' diberi hanya berdasarkan nilai ujian tertulis, mengabaikan bentuk prestasi lain"],groups:["Bias keterwakilan","Bias historis","Bias pengukuran"],answer:{"Bias keterwakilan":["Data suara 90% dari satu negara berbahasa Inggris"],"Bias historis":["Data promosi jabatan dari era ketika perempuan jarang dipromosikan"],"Bias pengukuran":["Label 'berprestasi' diberi hanya berdasarkan nilai ujian tertulis, mengabaikan bentuk prestasi lain"]},explain:"Keterwakilan = siapa yang ada/tidak; historis = ketidakadilan masa lalu terekam; pengukuran = cara mengukur/melabeli yang timpang.",hint:"Apakah masalahnya siapa yang muncul, apa yang terjadi di masa lalu, atau bagaimana sesuatu diukur?"},
{n:22,type:"mcq",micro:"Bias agregasi",q:"Satu model dipakai untuk semua kelompok padahal kelompok berbeda punya pola berbeda (misalnya gejala penyakit yang muncul berbeda). Ini bisa membuat model...",options:["Menjadi terbaik di setiap kelompok; ia mempelajari semua pola gejala sekaligus","Bekerja baik untuk kelompok mayoritas tapi buruk untuk kelompok dengan pola berbeda","Adil untuk semua kelompok, dengan satu aturan yang sama bagi tiap orang"],answer:1,explain:"Menganggap 'satu ukuran untuk semua' bisa merugikan kelompok yang polanya tidak seperti mayoritas.",hint:"Apakah pola yang benar untuk mayoritas selalu benar untuk semua orang?"},
{n:23,type:"mcq",micro:"Mengukur keadilan: per kelompok",q:"Cara paling langsung memeriksa keadilan model:",options:["Lihat akurasi total saja; satu angka rata-rata dianggap cukup menunjukkan apakah semua kelompok diperlakukan sama","Tanyakan kepada pembuatnya apakah modelnya adil, lalu percaya jawabannya tanpa mengukur hasilnya pada tiap kelompok sendiri","Hitung akurasi & jenis kesalahan SECARA TERPISAH untuk tiap kelompok yang relevan, lalu bandingkan"],answer:2,explain:"Keadilan tidak terlihat dari angka total. Perbandingan per-kelompok mengungkap ketimpangan.",hint:"Bisakah 'total 85%' menyembunyikan '95% untuk grup A, 60% untuk grup B'?"},
{n:24,type:"mcq",micro:"Positif palsu yang timpang",q:"Model deteksi kecurangan ujian salah menuduh siswa jujur (positif palsu) 2× lebih sering untuk kelompok A daripada B. Ini masalah keadilan karena...",options:["Siswa kelompok A menanggung beban tuduhan salah lebih berat — perlakuan tidak setara","Positif palsu tidak penting; yang dihitung hanyalah jumlah kecurangan yang tertangkap","Tidak masalah selama akurasi total bagus; rata-ratanya tetap tinggi bagi seluruh siswa"],answer:0,explain:"Keadilan juga soal bagaimana KESALAHAN model tersebar. Kalau satu kelompok lebih sering dirugikan oleh kesalahan, itu tidak adil.",hint:"Siapa yang lebih sering dituduh salah, dan apakah itu adil?"},
{n:25,type:"mcq",micro:"Definisi keadilan bisa bertentangan",q:"Dua definisi keadilan: (a) 'tingkat penerimaan sama antar kelompok' dan (b) 'di antara yang memenuhi syarat, peluang diterima sama antar kelompok'. Keduanya...",options:["Dapat dipenuhi sekaligus oleh model yang cukup besar dan terlatih; memilih di antara keduanya dianggap tidak diperlukan","Bisa tidak mungkin dipenuhi sekaligus kalau kelompok punya distribusi berbeda — memilih definisi mana adalah keputusan nilai","Berbeda hanya soal nama; kedua definisi itu menghitung hal yang sama dan hasil angkanya identik pada data apa saja"],answer:1,explain:"Riset menunjukkan beberapa definisi keadilan secara matematis tidak bisa dipenuhi bersamaan. Harus ada pilihan sadar dan terbuka.",hint:"Apakah 'hasil yang sama' dan 'peluang yang sama' selalu bisa dicapai bersamaan?"},
{n:26,type:"mcq",micro:"Trade-off akurasi vs keadilan",q:"Kadang membuat model lebih adil sedikit menurunkan akurasi totalnya. Sikap yang bijak:",options:["Pilih akurasi total tertinggi dalam keadaan apa saja, walaupun ada kelompok yang terus-menerus dirugikan oleh modelnya di lapangan","Keadilan tidak sepadan dengan penurunan akurasi sekecil itu, jadi jangan mengorbankan angka akurasi total demi kelompok kecil","Pertimbangkan konteks: untuk keputusan yang memengaruhi hidup orang, keadilan sering layak diprioritaskan meski akurasi total sedikit turun"],answer:2,explain:"'Akurasi tertinggi' bukan satu-satunya tujuan. Untuk sistem yang berdampak pada orang, keseimbangan dengan keadilan penting.",hint:"Apakah model yang sedikit lebih akurat tapi merugikan satu kelompok adalah 'model terbaik'?"},
{n:27,type:"mcq",micro:"Proksi tersembunyi",q:"Model tidak memakai 'ras', tapi memakai 'kode pos'. Di daerah dengan pemisahan tempat tinggal, kode pos bisa menjadi...",options:["Proksi (pengganti) untuk ras — model tetap bisa membeda-bedakan berdasarkan ras secara tidak langsung","Fitur netral dan aman; kode pos hanyalah angka alamat yang tidak berkaitan dengan kelompok tertentu mana pun","Tidak berhubungan dengan kelompok, jadi memakai kode pos tidak mungkin menyebabkan perlakuan berbeda"],answer:0,explain:"Menghapus label sensitif tidak cukup kalau fitur lain sangat berkorelasi dengannya. Perlu memeriksa hasil, bukan hanya masukan.",hint:"Apakah kode pos bisa 'memberitahu' model tentang hal yang seharusnya tidak relevan?"},
{n:28,type:"tf",micro:"Keadilan butuh diperiksa terus-menerus",q:"Benar atau Salah: Kalau sebuah model sudah dipastikan adil saat diluncurkan, ia akan tetap adil selamanya tanpa perlu dipantau lagi.",answer:false,explain:"Keadilan bukan sifat sekali-cek. Bila data & dunia berubah, model yang tadinya adil bisa menjadi tidak adil, jadi keadilan perlu dipantau berkelanjutan.",hint:"Apakah pemeriksaan sekali di awal cukup untuk sesuatu yang terus berubah?"},
{n:29,type:"mcq",micro:"Audit sistem AI",q:"'Audit keadilan' sebuah sistem AI berarti...",options:["Membaca iklan dan siaran pers dari perusahaan pembuatnya, lalu menyimpulkan apakah sistemnya sudah adil bagi seluruh pengguna","Pemeriksaan sistematis oleh pihak yang kompeten (idealnya independen) atas data, kinerja per kelompok, dan dampak nyata","Menebak apakah sistemnya adil dari kesan pertama para pengguna, tanpa memeriksa data atau kinerja tiap kelompok"],answer:1,explain:"Audit yang serius memeriksa dari data sampai dampak, sebaiknya oleh pihak yang tidak berkepentingan menyembunyikan masalah.",hint:"Siapa yang sebaiknya memeriksa: pembuatnya sendiri, atau pihak luar?"},
{n:30,type:"order",micro:"Memeriksa keadilan sebuah model",q:"Urutkan langkah memeriksa apakah sebuah model adil.",items:["Tentukan kelompok mana yang relevan & definisi keadilan yang dipakai (dengan masukan pihak terdampak)","Ukur kinerja & jenis kesalahan secara terpisah per kelompok","Selidiki penyebab ketimpangan yang ditemukan (data, proksi, label)","Perbaiki (data lebih representatif, penyesuaian) & pantau setelah diterapkan"],answer:[0,1,2,3],explain:"Tentukan kelompok & definisi → ukur per kelompok → selidiki penyebab → perbaiki & pantau.",hint:"Kamu perlu tahu 'adil menurut definisi apa' sebelum bisa mengukurnya."},
{n:31,type:"mcq",micro:"Keseimbangan data",q:"Salah satu cara memperbaiki bias keterwakilan:",options:["Mengganti nama kelompok di data menjadi kode angka untuk menyembunyikan dari model siapa yang kurang terwakili","Membiarkan masalahnya; model dianggap akan belajar sendiri mengenali kelompok yang jarang muncul tanpa data tambahan","Sengaja mengumpulkan lebih banyak data dari kelompok yang kurang terwakili sampai proporsinya wajar"],answer:2,explain:"Menyeimbangkan data (lewat pengumpulan tambahan yang terarah) membantu model belajar pola tiap kelompok dengan baik.",hint:"Kalau satu kelompok jarang muncul, apa yang perlu ditambah?"},
{n:32,type:"mcq",micro:"Label yang lebih baik",q:"Untuk mengurangi bias label pada 'komentar kasar/sopan':",options:["Libatkan pelabel dari latar beragam, sepakati kriteria eksplisit, dan periksa di mana mereka tidak sepakat","Pakai satu pelabel yang bekerja cepat tanpa kriteria tertulis, dan tidak perlu membandingkan hasilnya dengan pelabel lain","Biarkan model melabeli sendiri semua komentar, lalu anggap hasilnya benar tanpa diperiksa pelabel manusia"],answer:0,explain:"Label yang beragam & berpedoman jelas mengurangi bias satu perspektif dan menghasilkan model yang lebih seimbang.",hint:"Bagaimana membuat definisi 'kasar' tidak hanya mencerminkan satu budaya?"},
{n:33,type:"mcq",micro:"Keadilan vs kesamaan hasil",q:"Untuk beasiswa berbasis kebutuhan, 'adil' mungkin justru berarti...",options:["Yang datanya paling lengkap mendapat prioritas, tanpa memandang apakah ia memang paling membutuhkan bantuan itu","Memberi lebih banyak dukungan ke yang lebih membutuhkan — bukan memberi jumlah yang persis sama ke semua orang","Setiap penerima mendapat jumlah yang persis sama, tanpa melihat perbedaan kebutuhan atau keadaan hidupnya"],answer:1,explain:"Keadilan tidak selalu berarti 'sama rata'. Kadang berarti memperhitungkan titik awal yang berbeda.",hint:"Apakah memberi kacamata hanya ke yang butuh itu tidak adil bagi yang penglihatannya sudah bagus?"},
{n:34,type:"mcq",micro:"Bias yang tidak terlihat tanpa data kelompok",q:"Untuk MEMERIKSA keadilan model, kita sering butuh mengetahui kelompok tiap orang dalam data uji — meski model tidak memakainya. Ini menciptakan ketegangan dengan...",options:["Kecepatan: mengumpulkan data kelompok membuat model berjalan lebih lambat dan menghabiskan memori komputer yang besar","Akurasi: model yang diuji per kelompok menjadi kurang tepat dan hasil totalnya turun drastis pada data uji","Privasi: mengumpulkan data kelompok sensitif punya risiko sendiri; perlu ditangani hati-hati (izin, keamanan, tujuan terbatas)"],answer:2,explain:"Memeriksa keadilan butuh data kelompok, tapi data itu sensitif. Keduanya nilai penting yang harus diseimbangkan.",hint:"Untuk mengecek apakah adil per kelompok, apa yang perlu kamu ketahui — dan apa risikonya?"},
{n:35,type:"mcq",micro:"Bias dalam apa yang dioptimalkan",q:"Model rekomendasi berita dioptimalkan untuk 'klik'. Konten yang membuat marah sering lebih banyak diklik. Akibatnya sistem...",options:["Bisa condong menyebarkan konten yang memancing emosi, bukan yang informatif — bias dari ukuran yang dipilih","Tetap netral; sistem hanya menampilkan yang diminta pengguna, bukan memilih konten tertentu","Menyebarkan berita yang paling akurat; klik terbanyak dianggap berarti isinya telah terbukti benar"],answer:0,explain:"Ukuran keberhasilan yang dipilih membentuk perilaku sistem. 'Klik' bukan sama dengan 'bermanfaat' atau 'benar'.",hint:"Jenis konten apa yang paling banyak diklik, dan apakah itu yang kita inginkan?"},
{n:36,type:"tf",micro:"Keadilan adalah tanggung jawab manusia",q:"Benar atau Salah: Model AI punya rasa keadilan bawaan, jadi ia akan otomatis membuat keputusan yang adil tanpa perlu manusia mengatur atau memeriksanya.",answer:false,explain:"Model tidak punya rasa keadilan bawaan. Memastikan sistem AI adil adalah tanggung jawab manusia yang merancang, melatih, dan menerapkannya — keadilan harus sengaja dirancang, diukur, dan dijaga.",hint:"Siapa yang harus memastikan sistem ini adil?"},
{n:37,type:"mcq",micro:"Menguji dengan kasus batas",q:"Menguji model dengan contoh dari kelompok yang jarang & situasi tidak biasa berguna karena...",options:["Kasus batas tidak penting; situasi jarang tidak memengaruhi hidup nyata","Di situlah model sering paling lemah — dan orang di situasi itu paling berisiko dirugikan","Contoh umum sudah cukup; model yang benar pada kasus biasa dianggap juga benar pada kasus langka"],answer:1,explain:"Model biasanya kuat di kasus umum. Kelemahan & ketidakadilan sering muncul di kasus yang jarang.",hint:"Di mana model paling mungkin gagal, dan siapa yang di sana?"},
{n:38,type:"mcq",micro:"Transparansi tentang keterbatasan",q:"Cara yang jujur menyajikan sebuah model:",options:["Hanya menampilkan angka akurasi terbaik yang pernah dicapai, untuk meyakinkan pengguna memakai model itu di berbagai tempat","Tidak menyebut keterbatasan model dan hanya memuji kelebihannya, tanpa membahas kekurangannya sedikit pun","Menyebutkan untuk siapa & situasi apa ia bekerja baik, dan di mana ia kurang andal — bukan hanya angka akurasi tunggal"],answer:2,explain:"Menyatakan batas & ketimpangan model membantu orang memakainya dengan tepat dan tidak mengandalkannya di tempat yang salah.",hint:"Apa yang perlu diketahui pengguna selain 'akurasi 92%'?"},
{n:39,type:"mcq",micro:"Bias bisa muncul di setiap tahap",q:"Bias bisa masuk ke sistem AI di tahap...",options:["Semua tahap: memilih masalah, mengumpulkan data, melabeli, memilih fitur & ukuran, melatih, mengevaluasi, dan menerapkan","Hanya saat mengumpulkan data; tahap sesudahnya hanyalah perhitungan netral yang tidak memuat pilihan manusia","Hanya saat melatih model; tahap sebelum dan sesudahnya tidak memuat keputusan yang bisa memengaruhi hasil"],answer:0,explain:"Setiap keputusan manusia sepanjang alur bisa memasukkan bias. Pemeriksaan perlu di banyak titik.",hint:"Di mana saja manusia membuat pilihan dalam membangun AI?"},
{n:40,type:"open",micro:"Merancang pemeriksaan keadilan",q:"Sebuah kota ingin memakai model untuk memprioritaskan perbaikan jalan (menandai jalan yang paling butuh diperbaiki dari foto & laporan warga). Rancang pemeriksaan keadilan: (1) kelompok/wilayah mana yang relevan, (2) sumber data & bias yang mungkin, (3) apa yang kamu ukur per wilayah, (4) satu cara memperbaiki bila ditemukan ketimpangan.",explain:"Jawaban baik mengenali bias pelaporan (kelompok yang jarang melapor jadi tak terlihat), mengukur terhadap 'kebenaran lapangan' yang independen dari laporan, dan mengusulkan pengumpulan data yang merata.",hint:"Siapa yang jarang melapor, dan bagaimana ketiadaan laporan mereka menyesatkan model?",sample:"(1) Wilayah relevan: lingkungan kaya vs kurang mampu, pusat vs pinggiran, area dengan akses internet baik vs buruk. (2) Sumber: foto jalan + laporan warga lewat aplikasi. Bias: warga di area kurang mampu / minim internet lebih jarang melapor, jadi jalan rusak di sana kurang tercatat → model belajar 'area yang jarang dilaporkan = jalannya baik-baik saja', memperkuat ketimpangan perawatan. (3) Ukur: proporsi jalan yang benar-benar rusak (dari survei lapangan acak yang tidak bergantung laporan) yang ditandai model, DIPISAH per jenis wilayah; bandingkan. (4) Perbaikan: lengkapi data dengan survei lapangan berkala yang menjangkau semua wilayah secara merata (bukan hanya mengandalkan laporan warga), dan beri bobot khusus untuk area yang secara historis kurang terlayani."},
{n:41,type:"mcq",micro:"Mitigasi di data",q:"Menangani bias 'di sumber data' berarti...",options:["Mengabaikan data lama dan hanya memperbaiki keluaran model setelah ia selesai dilatih dan dipakai pengguna","Mengumpulkan data yang lebih representatif, memperbaiki label, atau menyeimbangkan proporsi kelompok sebelum melatih","Menambah jumlah parameter model untuk menutupi pola yang keliru di dalam data dengan perhitungan"],answer:1,explain:"Salah satu tempat menangani bias adalah datanya sendiri — sebelum model belajar dari yang timpang.",hint:"Kalau bahan bakunya bermasalah, di mana perbaikan yang paling mendasar?"},
{n:42,type:"mcq",micro:"Mitigasi saat pelatihan/keluaran",q:"Selain memperbaiki data, bias bisa ditangani dengan...",options:["Menyembunyikan hasil per kelompok dari laporan supaya perbedaan antar kelompok tidak terlihat oleh pengguna","Mengandalkan niat baik pembuat model dan menunggu keluhan datang dari pengguna yang merasa dirugikan","Teknik saat pelatihan atau penyesuaian keluaran agar hasil lebih seimbang antar kelompok, dengan pemantauan"],answer:2,explain:"Ada metode teknis untuk mendorong keadilan selama atau setelah pelatihan — tapi semua perlu diukur dampaknya.",hint:"Apakah perbaikan bias hanya bisa dilakukan pada data mentah?"},
{n:43,type:"mcq",micro:"Dokumentasi model",q:"'Kartu model' (model card) adalah dokumen yang menjelaskan...",options:["Untuk apa model dibuat, data latihnya, kinerja per kelompok, keterbatasan, dan penggunaan yang tidak disarankan","Harga model, jumlah pembelinya, dan peringkat popularitasnya di toko aplikasi pada bulan peluncuran","Nama pembuatnya, tanggal peluncuran, serta warna dan logo yang dipakai pada tampilan aplikasinya"],answer:0,explain:"Dokumentasi seperti ini membantu pengguna memahami apakah model cocok & aman untuk keperluan mereka.",hint:"Apa yang perlu diketahui seseorang sebelum memakai sebuah model?"},
{n:44,type:"mcq",micro:"Akuntabilitas",q:"Kalau sistem AI membuat keputusan yang merugikan seseorang secara tidak adil, yang bertanggung jawab adalah...",options:["Tidak ada pihak yang dapat disalahkan; keputusan mesin dianggap kejadian alam","Lembaga & orang yang merancang, memilih, dan menerapkan sistem itu — bukan 'AI'","AI itu sendiri; ia yang memutuskan dan manusia hanya menyalakan komputernya saja"],answer:1,explain:"Menyebut 'AI yang memutuskan' menyamarkan tanggung jawab manusia. Akuntabilitas tetap pada pihak yang membangun & memakai.",hint:"Bisakah sebuah alat dimintai pertanggungjawaban di pengadilan?"},
{n:45,type:"mcq",micro:"Hak untuk penjelasan & banding",q:"Untuk keputusan penting yang dibantu AI (penolakan bantuan, penilaian siswa), orang yang terdampak sebaiknya bisa...",options:["Tidak diberi tahu bahwa AI dipakai; pengetahuan itu dianggap hanya membingungkan dan tidak diperlukan","Menerima hasilnya begitu saja tanpa penjelasan dan tanpa kesempatan meminta peninjauan ulang","Mengetahui bahwa AI dipakai, memahami faktor utamanya, dan mengajukan peninjauan oleh manusia"],answer:2,explain:"Transparansi & jalur banding adalah pengaman penting terhadap kesalahan & ketidakadilan sistem.",hint:"Kalau kamu ditolak oleh sistem, apa yang berhak kamu ketahui & lakukan?"},
{n:46,type:"mcq",micro:"Keadilan bergantung konteks",q:"Definisi 'adil' yang tepat untuk 'model rekomendasi film' berbeda dari untuk 'model diagnosis penyakit' karena...",options:["Taruhannya berbeda — rekomendasi film salah itu ringan; diagnosis salah bisa fatal, jadi standar keadilan & akurasinya jauh lebih ketat","Keduanya butuh standar yang persis sama; kesalahan di bidang mana pun sama beratnya bagi orang yang terkena dampaknya di kehidupan sehari-hari","Keadilan tidak bergantung pada konteks, jadi aturan yang sama dipakai untuk semua jenis sistem dan semua jenis keputusan tanpa penyesuaian"],answer:0,explain:"Seberapa ketat keadilan & pengawasan yang dibutuhkan sepadan dengan seberapa besar dampak kesalahan pada hidup orang.",hint:"Apa akibat terburuk kesalahan di tiap kasus?"},
{n:47,type:"order",micro:"Menangani laporan bias dari pengguna",q:"Pengguna melaporkan bahwa sebuah fitur AI bekerja buruk untuk kelompoknya. Urutkan respons yang bertanggung jawab.",items:["Terima laporan dengan serius & kumpulkan contoh spesifik","Ukur kinerja model untuk kelompok itu dibanding kelompok lain","Selidiki penyebab (data kurang, proksi, label bias)","Perbaiki, uji ulang lintas kelompok, dan beri tahu pengguna hasilnya"],answer:[0,1,2,3],explain:"Dengarkan → ukur → selidiki penyebab → perbaiki & komunikasikan.",hint:"Sebelum memperbaiki, buktikan & pahami masalahnya dulu."},
{n:48,type:"mcq",micro:"Keterlibatan komunitas",q:"Melibatkan orang dari kelompok yang terdampak dalam merancang & menguji sistem AI...",options:["Tidak perlu; tim teknis pembuatnya sudah paling mengerti sistemnya dan cukup merancang sendiri","Membantu menangkap masalah keadilan yang tidak terlihat oleh pembuat, dan membangun kepercayaan","Hanya memperlambat pekerjaan tanpa manfaat berarti; pendapat orang terdampak tidak mengubah kualitas"],answer:1,explain:"Orang yang berbeda melihat masalah berbeda. Keterlibatan yang terdampak menghasilkan sistem yang lebih adil & lebih diterima.",hint:"Siapa yang paling tahu bagaimana rasanya dirugikan oleh sistem seperti ini?"},
{n:49,type:"mcq",micro:"Bias dalam memilih masalah",q:"Sebuah perusahaan membangun AI untuk 'mendeteksi karyawan berisiko keluar' tapi tidak untuk 'mendeteksi kondisi kerja yang membuat orang ingin keluar'. Ini menunjukkan bias sudah muncul di tahap...",options:["Melatih model; pilihan algoritma dianggap menentukan kelompok yang akan dianggap berisiko tinggi","Menerapkan model; bias baru dianggap muncul ketika pengguna mulai membaca hasil di layar aplikasi","Memilih masalah — pertanyaan yang diajukan membentuk siapa yang 'diawasi' dan siapa yang tidak"],answer:2,explain:"Keputusan tentang MASALAH APA yang layak dipecahkan oleh AI adalah pilihan bernilai yang bisa menguntungkan sebagian pihak.",hint:"Siapa yang diuntungkan dari mengawasi karyawan, bukan kondisi kerja?"},
{n:50,type:"mcq",micro:"Keadilan & data yang hilang secara sistematis",q:"Kalau kelompok tertentu sengaja menghindari mencatatkan diri (karena takut disalahgunakan), 'menambah data mereka'...",options:["Bukan solusi sederhana — perlu membangun kepercayaan & perlindungan dulu, atau merancang sistem yang tidak menghukum ketiadaan data","Cukup paksa mereka mendaftar, tanpa memedulikan rasa takut atau alasan mengapa mereka menghindar dari pencatatan itu","Abaikan kelompok itu; datanya tidak tersedia dan mereka tidak perlu diperhitungkan dalam sistem yang dibuat"],answer:0,explain:"Bias data kadang berakar pada ketidakpercayaan yang beralasan. Menanganinya butuh lebih dari sekadar teknis.",hint:"Mengapa sebuah kelompok mungkin menghindari tercatat, dan apa yang harus berubah dulu?"},
{n:51,type:"open",micro:"Menyeimbangkan keadilan yang bertentangan",q:"Sebuah program memakai model untuk memilih 100 siswa yang mendapat laptop gratis. Definisi 'adil' yang diusulkan: (A) proporsi penerima per sekolah sama dengan proporsi siswa per sekolah; (B) laptop diberikan ke 100 siswa dengan 'skor kebutuhan' tertinggi tanpa memandang sekolah. Jelaskan kelebihan & kekurangan masing-masing, dan usulkan pendekatan.",explain:"Jawaban baik menunjukkan bahwa kedua definisi keadilan valid tapi bertabrakan, mengenali risiko bias dalam 'skor kebutuhan', dan mengusulkan kompromi + verifikasi + keterlibatan.",hint:"Tidak ada jawaban yang benar sepenuhnya — tunjukkan trade-off-nya dan cara menyeimbangkannya.",sample:"(A) Proporsional per sekolah: + tiap sekolah merasa terwakili & tidak ada yang 'kalah total'; − kalau kebutuhan tidak merata (satu sekolah jauh lebih miskin), siswa sangat membutuhkan di sana bisa tidak dapat sementara siswa kurang membutuhkan di sekolah lain dapat. (B) Skor kebutuhan tertinggi: + laptop menuju yang paling butuh; − 'skor kebutuhan' bisa bias (bergantung data yang tersedia; sekolah dengan pencatatan lebih baik terlihat lebih 'butuh'); satu sekolah bisa mendominasi & sekolah lain tidak dapat sama sekali, memicu rasa tidak adil & masalah politik. Usulan: gabungan — jamin minimal beberapa laptop per sekolah (agar tidak ada yang nol), lalu alokasikan sisanya berdasarkan skor kebutuhan; pastikan skor kebutuhan diverifikasi lapangan, bukan hanya dari data digital; libatkan perwakilan sekolah dalam menyepakati kriteria & tinjau hasilnya."},
{n:52,type:"mcq",micro:"Menguji sebelum & sesudah perubahan",q:"Setelah menerapkan perbaikan bias, langkah penting:",options:["Hentikan pemantauan; perbaikan dianggap sudah diterapkan, lalu fokus membuat fitur baru yang akan diluncurkan pada pengguna","Ukur ulang keadilan lintas kelompok untuk memastikan perbaikan benar-benar bekerja dan tidak menciptakan ketimpangan baru","Anggap sudah beres; perbaikan dilakukan oleh tim yang berpengalaman, dan pengukuran ulang hanya menambah biaya"],answer:1,explain:"Perbaikan bias bisa punya efek samping. Pengukuran ulang memastikan keadaan benar-benar membaik.",hint:"Bagaimana kamu tahu perbaikanmu berhasil?"},
{n:53,type:"tf",micro:"Tidak ada model yang 'bebas nilai'",q:"Benar atau Salah: Setiap sistem AI mengandung pilihan nilai — masalah apa yang dipecahkan, data apa yang dipakai, keadilan seperti apa yang dikejar — sehingga tidak ada yang benar-benar 'objektif & bebas nilai'.",answer:true,explain:"'Objektif' sering menyembunyikan pilihan yang sudah dibuat. Menyadari nilai yang tertanam adalah langkah pertama menanganinya.",hint:"Bisakah ada AI tanpa seseorang memutuskan apa tujuannya?"},
{n:54,type:"mcq",micro:"Bias yang menguntungkan mayoritas",q:"Sistem yang bekerja sangat baik untuk 90% pengguna dan buruk untuk 10%...",options:["Sudah cukup baik; sebagian besar pengguna puas, dan 10% sisanya wajar diabaikan dan tidak perlu diteliti oleh pembuatnya","Dinilai adil; angka total yang tinggi dianggap membuktikan bahwa kelompok kecil pun tidak menanggung kerugian berarti dari sistem itu","Bisa terlihat 'sukses' dari angka total & terus dipakai, sementara 10% yang dirugikan diabaikan — perlu perhatian khusus pada yang tertinggal"],answer:2,explain:"Keputusan berbasis 'kebanyakan orang' bisa secara sistematis mengabaikan minoritas. Keadilan menuntut melihat mereka.",hint:"Kalau kamu bagian dari 10% yang dirugikan setiap hari, apakah 'total 90% puas' menghiburmu?"},
{n:55,type:"mcq",micro:"Batas perbaikan teknis",q:"Kalau sebuah bias berakar pada ketidakadilan struktural di masyarakat, perbaikan teknis pada model...",options:["Bisa membantu tapi tidak menyelesaikan akar masalahnya; kadang keputusan yang tepat adalah TIDAK memakai AI untuk keputusan itu","Cukup untuk menyelesaikan seluruh masalah; bias di masyarakat hanyalah cerminan data yang bisa dibersihkan","Mustahil membantu; ketidakadilan masyarakat dianggap tidak berkaitan dengan model dan perbaikan teknis sia-sia untuk dilakukan oleh tim mana pun"],answer:0,explain:"Beberapa masalah keadilan terlalu dalam untuk 'diperbaiki' dengan menyesuaikan model. Menyadari batas ini penting.",hint:"Bisakah menyetel model memperbaiki ketimpangan yang sudah ada di dunia sebelum data dikumpulkan?"},
{n:56,type:"mcq",micro:"Keadilan sebagai proses, bukan status",q:"Cara terbaik memandang keadilan sistem AI:",options:["Mustahil dicapai penuh, jadi tidak usah dicoba dan tidak perlu diukur, diperbaiki, atau dipantau","Proses berkelanjutan: tetapkan definisi, ukur, perbaiki, pantau, libatkan yang terdampak — berulang","Sesuatu yang dicek sekali sebelum peluncuran lalu dianggap selesai, tanpa pemantauan atau perbaikan lanjutan"],answer:1,explain:"Keadilan tidak pernah 'selesai'. Ia dijaga lewat pemeriksaan & perbaikan yang terus berjalan.",hint:"Apakah menjaga sesuatu tetap adil lebih mirip 'tugas sekali' atau 'perawatan rutin'?"},
{n:57,type:"tf",micro:"Menolak sistem yang tidak bisa dibuat adil",q:"Benar atau Salah: Kalau sebuah sistem AI sudah dibangun dan berfungsi, ia wajib diterapkan meski setelah usaha serius tetap tidak bisa dibuat cukup adil untuk keputusan berdampak besar.",answer:false,explain:"'Bisa dibangun' tidak berarti 'harus dipakai'. Untuk keputusan penting, memilih untuk tidak menerapkan AI yang tetap bias adalah pilihan yang bertanggung jawab.",hint:"Apakah setiap sistem yang bisa dibuat wajib digunakan?"},
{n:58,type:"mcq",micro:"Bias dalam evaluasi",q:"Kalau data uji yang dipakai menilai model juga bias (kurang mewakili kelompok tertentu), maka...",options:["Evaluasi tetap akurat; kekurangan data uji dianggap tidak memengaruhi perhitungan keadilan sedikit pun","Tidak masalah; data uji hanya dipakai menghitung akurasi dan bukan untuk menilai keadilan model","Skor keadilan yang bagus bisa palsu — kelompok yang kurang di data uji juga kurang di pengukuran keadilannya"],answer:2,explain:"Keadilan tidak bisa diukur dengan benar memakai data uji yang sendiri tidak representatif.",hint:"Kalau kelompok X hampir tidak ada di data uji, bisakah kamu tahu model adil untuk mereka?"},
{n:59,type:"mcq",micro:"Menyeimbangkan privasi & pemeriksaan keadilan",q:"Untuk memeriksa keadilan tanpa menyimpan data sensitif jangka panjang, salah satu pendekatan:",options:["Kumpulkan data kelompok hanya sementara, untuk audit tertentu, dengan izin & keamanan ketat, lalu hapus","Simpan data sensitif tanpa batas waktu di satu tempat terbuka untuk memudahkan peneliti luar memeriksanya kapan saja","Jangan memeriksa keadilan; mengumpulkan data kelompok dianggap melanggar privasi dalam setiap keadaan"],answer:0,explain:"Ada cara menyeimbangkan: pemeriksaan keadilan yang perlu data kelompok bisa dilakukan dengan tata kelola data yang hati-hati.",hint:"Bisakah kamu memeriksa keadilan tanpa menyimpan data sensitif tiap orang selamanya?"},
{n:60,type:"open",micro:"Rencana keadilan untuk sistem AI",q:"Sebuah sekolah akan memakai model untuk menyarankan siswa mana yang butuh bimbingan belajar tambahan. Buat rencana keadilan singkat: (1) kelompok relevan & definisi 'adil' yang dipilih + alasan, (2) data & bias yang mungkin, (3) apa yang diukur & bagaimana, (4) peran manusia, (5) transparansi ke siswa/orang tua, (6) rencana pemantauan.",explain:"Rencana baik memilih definisi keadilan yang sesuai tujuan, mengenali bias sumber data (catatan guru, jenis ujian, data pindahan), mengukur per kelompok termasuk positif palsu, menempatkan manusia sebagai pengambil keputusan, transparan, dan memantau berkelanjutan.",hint:"Perhatikan: positif palsu di sini (disarankan padahal tidak butuh) bisa menstigma — itu juga soal keadilan.",sample:"(1) Kelompok: jenis kelamin, latar ekonomi, siswa dengan kebutuhan khusus, kelas asal. Definisi adil: di antara siswa dengan tingkat kesulitan belajar yang sebanding, peluang disarankan untuk bimbingan sama antar kelompok (bukan sekadar 'jumlah sama') — karena tujuannya menjangkau yang benar-benar butuh. (2) Data: nilai, kehadiran, catatan guru. Bias: catatan guru bisa mencerminkan bias guru; nilai ujian tertulis bisa merugikan siswa yang kesulitannya bukan akademik murni; siswa yang pindahan datanya sedikit. (3) Ukur: proporsi siswa yang benar-benar kesulitan (dari asesmen menyeluruh) yang tertangkap model, dipisah per kelompok; juga positif palsu (disarankan padahal tidak butuh — bisa menstigma). (4) Manusia: model hanya membuat DAFTAR SARAN; wali kelas & guru BK meninjau tiap nama sebelum tindakan; siswa bisa juga mengajukan diri. (5) Transparansi: jelaskan ke siswa & orang tua bahwa daftar dibantu model, faktor apa yang dilihat, bahwa keputusan akhir oleh guru, dan bimbingan bersifat dukungan (bukan hukuman/label). (6) Pemantauan: tiap semester, bandingkan kinerja per kelompok & kumpulkan umpan balik dari siswa yang disarankan; sesuaikan bila ada kelompok yang terlewat atau distigma."},
{n:61,type:"mcq",micro:"Keadilan individual vs kelompok",q:"Model bisa 'adil secara kelompok' (tingkat penerimaan sama antar kelompok) tapi menghasilkan keputusan yang terasa tidak adil bagi individu tertentu (dua orang sangat mirip, hasil berbeda). Ini menunjukkan...",options:["Keadilan kelompok sudah cukup untuk setiap konteks, jadi satu definisi itu memadai dan tidak berbenturan dengan definisi lain yang pernah diusulkan","Definisi keadilan yang berbeda menyoroti hal berbeda, dan bisa saling tegang — perlu pilihan sadar tentang mana yang diutamakan di konteks ini","Keadilan itu mustahil dicapai, jadi tidak ada gunanya memilih definisi dan semua keputusan dianggap sama saja bagi yang terkena"],answer:1,explain:"Keadilan individual (perlakuan konsisten untuk kasus serupa) dan keadilan kelompok (hasil setara antar kelompok) tidak selalu sejalan.",hint:"Bisakah 'adil untuk kelompok' dan 'adil untuk tiap individu' berbenturan?"},
{n:62,type:"mcq",micro:"Bias yang muncul dari 'menghapus bias'",q:"Sebuah tim menyesuaikan model agar tingkat penerimaan sama antar dua kelompok. Tapi caranya membuat model menolak sebagian pelamar sangat memenuhi syarat dari satu kelompok. Pelajaran:",options:["Perbaikan keadilan tidak punya efek samping; cukup menyamakan satu angka tanpa memeriksa dampak lain","Perbaikan keadilan sebaiknya dihindari; setiap perubahan pada model hanya membuat keadaan lebih buruk","Setiap metode 'perbaikan keadilan' punya trade-off; perlu diukur dampak penuhnya, bukan hanya satu angka keadilan"],answer:2,explain:"'Menyeimbangkan' satu ukuran bisa merugikan pihak lain. Perbaikan harus dinilai dari dampak menyeluruh & keterlibatan yang terdampak.",hint:"Kalau kamu memaksa dua angka jadi sama, apa yang mungkin bergeser sebagai gantinya?"},
{n:63,type:"tf",micro:"Bias bisa halus & tidak terduga",q:"Benar atau Salah: Bias dalam sistem AI sering muncul di tempat yang tidak diduga pembuatnya, sehingga pemeriksaan aktif (bukan mengandalkan 'kami tidak bermaksud bias') diperlukan.",answer:true,explain:"Niat baik tidak mencegah bias. Hanya pengukuran & pemeriksaan yang sengaja bisa menemukannya.",hint:"Apakah 'kami tidak berniat begitu' cukup untuk memastikan sistem adil?"},
{n:64,type:"mcq",micro:"Siapa yang menanggung risiko kesalahan",q:"Dalam merancang model, pertanyaan keadilan yang penting:",options:["Kalau model salah, SIAPA yang menanggung akibatnya — dan apakah beban itu jatuh lebih berat pada kelompok yang sudah rentan?","Berapa akurasi totalnya? Satu angka itu dianggap cukup menunjukkan apakah ada kelompok yang menanggung beban lebih besar","Seberapa cepat model berjalan dan berapa biaya komputasinya? Kecepatan dianggap menentukan keadilan hasilnya bagi para pengguna"],answer:0,explain:"Keadilan juga soal distribusi risiko: sistem yang kesalahannya selalu merugikan pihak yang sama & yang paling rentan adalah tidak adil.",hint:"Ketika sistem gagal, siapa yang paling terluka?"},
{n:65,type:"mcq",micro:"'AI lebih objektif dari manusia'",q:"Klaim 'ganti keputusan manusia dengan AI supaya lebih objektif' perlu disikapi hati-hati karena...",options:["Manusia tidak bias saat memutuskan, artinya AI tidak bisa lebih baik daripada manusia, dan penggantian itu merugikan orang yang dinilai oleh model itu","AI bisa membuat bias menjadi konsisten & berskala besar (semua orang dinilai oleh model bias yang sama), dan lebih sulit digugat daripada keputusan satu orang","AI bersifat objektif dan tidak berat sebelah, jadi mengganti manusia dengan AI menghilangkan bias dan keputusannya tak perlu dipertanyakan oleh pihak yang dinilai"],answer:1,explain:"Mengotomatiskan keputusan bisa menyebarkan satu bias ke semua kasus sekaligus, dengan kesan 'netral' yang menyulitkan protes.",hint:"Apa yang lebih berbahaya: satu juri bias, atau satu model bias yang menilai sejuta orang?"},
{n:66,type:"mcq",micro:"Menilai audit yang dilakukan sendiri",q:"Sebuah perusahaan merilis 'audit keadilan internal' yang menyatakan modelnya adil. Sikap kritis:",options:["Percaya penuh; mereka pembuatnya dan paling tahu modelnya, dan pemeriksaan dari pihak lain tidak diperlukan dalam laporan itu","Setiap audit sama nilainya, dilakukan oleh pihak mana saja dan memakai data jenis apa saja, tanpa perlu dibedakan","Audit oleh pihak yang berkepentingan menyembunyikan masalah kurang bisa dipercaya; audit independen & data yang bisa diperiksa lebih kuat"],answer:2,explain:"Konflik kepentingan memengaruhi audit. Pemeriksaan independen & transparansi data memberi keyakinan lebih.",hint:"Apakah nilai rapor yang kamu tulis sendiri sekuat nilai dari guru?"},
{n:67,type:"tf",micro:"Data besar tidak menjamin data adil",q:"Benar atau Salah: Kalau sebuah kumpulan data sudah sangat besar (miliaran contoh), ia pasti mewakili semua kelompok dengan baik.",answer:false,explain:"Jumlah besar sering datang dari sumber yang sama-sama timpang (mis. internet berbahasa Inggris). Ukuran tidak sama dengan keterwakilan — data besar pun bisa hampir tidak memuat sebagian kelompok.",hint:"Kalau semua miliaran contoh dari satu jenis sumber, apakah keragamannya bertambah?"},
{n:68,type:"mcq",micro:"Keadilan antar generasi model",q:"Model baru dilatih sebagian dari keluaran model lama yang bias. Risikonya:",options:["Bias model lama bisa 'diwariskan' & diperkuat, karena keluarannya menjadi data latih yang tampak 'normal'","Model baru otomatis lebih adil, karena data dari model lama sudah disaring sehingga bias bawaannya hilang","Tidak ada hubungan, karena keluaran model lama hanyalah teks biasa yang tidak memuat pola apa-apa"],answer:0,explain:"Kalau data latih makin banyak berisi keluaran AI (yang mungkin bias), bias itu bisa mengeras alih-alih terkoreksi oleh keragaman dunia nyata.",hint:"Apa yang terjadi kalau salinan dibuat dari salinan yang cacat berkali-kali?"},
{n:69,type:"mcq",micro:"Menimbang manfaat & bahaya sebuah sistem",q:"Sebuah model membantu banyak orang tapi merugikan kelompok kecil secara serius. Keputusan yang bertanggung jawab...",options:["Batalkan sistem kalau ada satu orang pun yang dirugikan, berapa besar pun manfaat bagi orang banyak, tanpa mempertimbangkan apakah kerugian itu bisa dikurangi atau diperbaiki dulu","Tidak sekadar 'manfaat lebih besar dari kerugian' — pertimbangkan apakah kerugian pada kelompok kecil itu parah & tidak adil, dan apakah bisa dikurangi; kadang sistem harus ditahan sampai bisa diperbaiki","Pakai sistem asalkan lebih banyak orang diuntungkan, tanpa memikirkan beratnya kerugian yang ditanggung kelompok kecil itu, dan tanpa mencoba mengurangi atau memperbaiki dampak buruknya sebelum peluncuran"],answer:1,explain:"Keadilan bukan sekadar hitung-hitungan total. Kerugian serius & sistematis pada satu kelompok tidak otomatis 'terbayar' oleh manfaat bagi mayoritas.",hint:"Apakah menyakiti sedikit orang parah-parah selalu 'oke' asal banyak yang diuntungkan?"},
{n:70,type:"order",micro:"Menghadapi dugaan bias pada sistem yang sudah berjalan",q:"Media melaporkan bahwa sebuah sistem AI pemerintah mungkin bias terhadap kelompok tertentu. Urutkan respons yang bertanggung jawab.",items:["Kumpulkan data & periksa kinerja sistem per kelompok secara serius (idealnya oleh pihak independen)","Kalau ketimpangan nyata & serius, hentikan sementara pemakaian untuk keputusan berdampak besar","Selidiki penyebab & perbaiki, uji ulang lintas kelompok","Beri kompensasi/peninjauan ulang untuk keputusan yang terlanjur merugikan, & terapkan pemantauan berkelanjutan"],answer:[0,1,2,3],explain:"Periksa serius → hentikan sementara bila perlu → perbaiki & uji → tangani kerugian lalu & pantau ke depan.",hint:"Untuk keputusan berdampak besar, apa yang bijak sambil menyelidiki?"},
{n:71,type:"mcq",micro:"Bias & bahasa yang kurang sumber daya",q:"Model AI cenderung berkinerja lebih baik untuk bahasa dengan banyak teks digital. Untuk bahasa daerah dengan sedikit data, ini berarti...",options:["Bahasa itu tidak penting bagi perusahaan teknologi; penuturnya sedikit dan tidak memengaruhi kualitas layanan","Tidak ada dampak; model belajar bahasa baru dalam sekejap dan kualitasnya setara dengan bahasa besar lainnya","Penutur bahasa itu mendapat layanan AI yang lebih buruk — kesenjangan yang memperlebar ketimpangan digital yang sudah ada"],answer:2,explain:"Ketimpangan data bahasa menjadi ketimpangan akses & kualitas layanan AI — masalah keadilan lintas budaya.",hint:"Siapa yang dirugikan kalau AI hanya bekerja baik untuk bahasa-bahasa besar?"},
{n:72,type:"mcq",micro:"Menyeimbangkan kecepatan & keadilan",q:"Tekanan untuk 'meluncurkan produk cepat' sering berbenturan dengan pemeriksaan keadilan yang menyeluruh karena...",options:["Audit keadilan butuh waktu & sumber daya; melewatkannya mempercepat peluncuran tapi berisiko merugikan orang setelah dipakai luas","Keadilan tidak butuh waktu atau sumber daya tambahan, jadi pemeriksaannya tidak memperlambat peluncuran produk sedikit pun","Kecepatan peluncuran lebih penting daripada hal lain, dan pemeriksaan keadilan sebaiknya dilewati demi mengejar pesaing"],answer:0,explain:"Menunda pemeriksaan keadilan demi kecepatan memindahkan biaya ke orang yang dirugikan nanti. Untuk sistem berdampak, pemeriksaan harus dijadwalkan sebagai bagian wajib.",hint:"Siapa yang membayar 'harga' peluncuran yang terburu-buru?"},
{n:73,type:"tf",micro:"Keadilan butuh keragaman di tim pembuat",q:"Benar atau Salah: Tim pembuat yang beragam (latar, pengalaman, perspektif) lebih mungkin mengenali potensi bias & masalah keadilan lebih awal daripada tim yang homogen.",answer:true,explain:"Orang cenderung menyadari masalah yang relevan bagi pengalaman mereka. Tim homogen punya titik buta bersama.",hint:"Bisakah kamu mengenali masalah yang tidak pernah kamu alami tanpa ada yang menunjukkannya?"},
{n:74,type:"mcq",micro:"Bias dalam apa yang dianggap 'kesalahan'",q:"Model bahasa lebih sering menandai teks dalam gaya bahasa/dialek tertentu sebagai 'tidak baku' atau 'kurang profesional'. Ini bisa...",options:["Netral secara bahasa; model hanya menilai tata bahasa dan tidak mungkin mencerminkan prasangka tentang cara bicara tertentu","Merugikan penutur dialek itu (mis. dalam seleksi tulisan) — 'standar' yang dipakai model mencerminkan bias tentang cara bahasa yang 'benar'","Membantu para penutur menulis lebih baik dengan cara yang sama, dan penutur dialek tidak dirugikan oleh hasilnya di tempat kerja"],answer:1,explain:"Definisi 'baku/profesional' dalam data latih sering mencerminkan kelompok dominan. Menerapkannya sebagai standar bisa mendiskriminasi.",hint:"Siapa yang menentukan cara bicara/menulis mana yang 'profesional'?"},
{n:75,type:"mcq",micro:"Ketika 'tidak ada bias yang terdeteksi'",q:"Sebuah tim melaporkan 'kami menguji dan tidak menemukan bias'. Pertanyaan lanjutan yang penting:",options:["Berarti sistemnya adil bagi seluruh kelompok; sudah diuji dan tidak ada lagi kelompok atau bias yang perlu dicari oleh tim lain","Tidak perlu bertanya lagi; laporan pengujian dari tim pembuatnya dianggap sudah cukup lengkap dan dapat dipercaya sepenuhnya oleh masyarakat luas","Bias terhadap kelompok mana yang diuji? Dengan data uji seperti apa? Definisi keadilan mana? Mungkin ada kelompok/jenis bias yang belum diperiksa"],answer:2,explain:"'Tidak ditemukan' bergantung pada apa & bagaimana yang dicari. Pemeriksaan yang sempit bisa melewatkan bias nyata.",hint:"Apakah 'tidak menemukan' sama dengan 'tidak ada'?"},
{n:76,type:"mcq",micro:"Dampak keadilan pada kepercayaan",q:"Kalau sebuah kelompok berulang kali dirugikan oleh sistem AI sebuah lembaga, dampak jangka panjangnya...",options:["Kelompok itu kehilangan kepercayaan pada lembaga & mungkin menghindari layanannya — memperdalam ketimpangan","Dampak sosialnya kecil; kerugian berulang hanya dirasakan individu dan tidak memengaruhi hubungan dengan lembaga","Kepercayaan kelompok itu justru meningkat; mereka merasa sistem otomatis bekerja adil bagi semua"],answer:0,explain:"Ketidakadilan sistem merusak kepercayaan, dan hilangnya kepercayaan menciptakan kerugian lebih lanjut (orang menghindari layanan yang mereka butuhkan).",hint:"Apa yang kamu lakukan setelah berkali-kali diperlakukan tidak adil oleh sebuah kantor?"},
{n:77,type:"tf",micro:"Keadilan & akurasi bukan selalu bertentangan",q:"Benar atau Salah: Sering, memperbaiki keadilan (mis. menambah data yang kurang terwakili) juga MENINGKATKAN akurasi keseluruhan model, karena model jadi belajar pola yang benar untuk lebih banyak situasi.",answer:true,explain:"Trade-off keadilan-akurasi tidak selalu ada. Data yang lebih representatif sering menguntungkan keduanya.",hint:"Kalau model belajar lebih baik tentang kelompok yang tadinya terlewat, apakah akurasi totalnya bisa naik?"},
{n:78,type:"mcq",micro:"Regulasi & standar",q:"Aturan atau standar tentang keadilan AI (dari pemerintah/lembaga) berguna karena...",options:["Tidak diperlukan, karena perusahaan teknologi sudah memeriksa sendiri dan niat baik mereka cukup melindungi pengguna","Menetapkan syarat minimum & pemeriksaan yang wajib, sehingga keadilan tidak bergantung semata pada niat baik tiap perusahaan","Menghambat inovasi tanpa manfaat, sebab standar yang ditetapkan pihak luar hanya memperlambat perusahaan dan membuat produk mahal"],answer:1,explain:"Standar bersama menciptakan garis dasar & akuntabilitas, terutama untuk sistem yang memengaruhi hak & kesempatan orang.",hint:"Apakah keselamatan makanan sebaiknya bergantung hanya pada niat baik tiap produsen?"},
{n:79,type:"mcq",micro:"Menyeimbangkan banyak nilai",q:"Merancang sistem AI yang adil sering berarti menyeimbangkan...",options:["Hanya akurasi; keadilan, privasi, dan transparansi dapat diabaikan jika angka akurasinya sudah tinggi pada data uji","Hanya keadilan; akurasi, privasi, dan kegunaan tidak perlu diperhatikan bila hasilnya sudah setara antar kelompok","Akurasi, keadilan (dalam beberapa definisi), privasi, transparansi, dan kegunaan — tidak ada yang bisa dimaksimalkan sendirian"],answer:2,explain:"Nilai-nilai ini kadang bertegangan. Perancangan yang bertanggung jawab membuat trade-off secara sadar & terbuka, dengan masukan yang terdampak.",hint:"Bisakah kamu memaksimalkan privasi, akurasi, dan transparansi sekaligus tanpa kompromi?"},
{n:80,type:"open",micro:"Menganalisis dilema keadilan nyata",q:"Sebuah rumah sakit memakai model untuk memprioritaskan pasien mana yang mendapat program perawatan intensif tambahan. Model memakai 'biaya perawatan tahun lalu' sebagai perkiraan 'seberapa sakit'. Ternyata kelompok yang secara historis kurang mengakses layanan kesehatan (karena hambatan biaya/jarak) punya 'biaya tahun lalu' rendah meski kondisinya sama parah — sehingga jarang diprioritaskan. Analisis: (1) jenis bias apa ini, (2) mengapa 'biaya' adalah proksi yang bermasalah, (3) bagaimana memperbaikinya, (4) pelajaran umum tentang memilih apa yang diukur.",explain:"Jawaban baik mengenali bahwa 'biaya' mencampur 'kesakitan' dengan 'akses', menjelaskan bagaimana itu merugikan kelompok kurang terlayani, mengusulkan proksi yang lebih langsung + evaluasi per kelompok + keterlibatan, dan menarik pelajaran tentang proksi.",hint:"Apa yang memengaruhi 'biaya perawatan seseorang' selain seberapa sakit mereka?",sample:"(1) Bias pengukuran + bias historis: 'biaya perawatan' dipakai sebagai proksi untuk 'tingkat kesakitan', tapi biaya juga mencerminkan AKSES ke layanan, bukan hanya kondisi. (2) Kelompok dengan akses terbatas menghabiskan lebih sedikit meski sama sakitnya, jadi model menyimpulkan mereka 'lebih sehat' dan tidak butuh prioritas — memperkuat ketimpangan akses yang sudah ada. (3) Perbaikan: ganti label/proksi dengan ukuran kondisi kesehatan langsung (jumlah & jenis diagnosis, hasil pemeriksaan) alih-alih biaya; uji kinerja model per kelompok terhadap kebutuhan medis nyata; libatkan dokter & perwakilan komunitas dalam mendefinisikan 'prioritas'. (4) Pelajaran: proksi yang mudah diukur (biaya, klik, laporan) sering membawa bias tersembunyi karena dipengaruhi faktor selain yang ingin kita ukur. Selalu tanya: 'apa lagi yang memengaruhi angka ini, selain hal yang aku maksudkan?'"},
{n:81,type:"mcq",micro:"Keadilan di seluruh siklus hidup AI",q:"Memastikan keadilan sistem AI paling efektif bila...",options:["Dipertimbangkan di setiap tahap — memilih masalah, mengumpulkan data, melabeli, memilih ukuran, melatih, mengevaluasi, menerapkan, memantau","Hanya dicek di akhir sebelum peluncuran, setelah semua keputusan tentang data dan model selesai dibuat dan tidak bisa diubah lagi","Diserahkan sepenuhnya kepada tim hukum saja, dan tim teknis tidak perlu memikirkannya selama membangun dan melatih modelnya"],answer:0,explain:"Bias masuk di banyak titik; menangani keadilan hanya di akhir sering terlambat & mahal.",hint:"Kapan lebih murah mencegah bias: di awal perancangan atau setelah sistem berjalan?"},
{n:82,type:"mcq",micro:"Menilai klaim 'AI kami adil'",q:"Klaim 'sistem AI kami telah dipastikan adil' paling kredibel bila disertai...",options:["Logo dan sertifikat yang mengesankan, dipajang besar-besar untuk menenangkan pengguna tanpa perlu melihat data atau hasil ukurnya","Definisi keadilan yang dipakai, hasil pengukuran per kelompok, siapa yang mengaudit, data yang bisa diperiksa pihak lain, & rencana pemantauan","Sekadar pernyataan singkat dari perusahaan sendiri bahwa sistemnya adil, tanpa rincian cara pengukuran, auditor, maupun datanya"],answer:1,explain:"Keadilan yang kredibel bersifat spesifik & bisa diperiksa, bukan slogan.",hint:"Apa bukti konkret yang membuat klaim keadilan bisa dipercaya?"},
{n:83,type:"tf",micro:"Keadilan sempurna mungkin tidak tercapai, perbaikan tetap berarti",q:"Benar atau Salah: Karena keadilan yang sempurna sulit atau mustahil dicapai, tidak ada gunanya berusaha mengurangi ketimpangan dalam sistem AI.",answer:false,explain:"'Tidak bisa sempurna' bukan alasan untuk tidak berusaha. Mengurangi ketimpangan yang serius & terukur — kerugian nyata pada kelompok tertentu — tetap merupakan tujuan yang berharga dikejar.",hint:"Apakah 'tidak bisa 100% aman' berarti kita berhenti memakai sabuk pengaman?"},
{n:84,type:"mcq",micro:"Keadilan & pilihan untuk tidak mengotomatiskan",q:"Untuk keputusan yang sangat bergantung pada konteks manusia & nilai (mis. menilai penyesalan seseorang terdakwa remaja), sikap yang tepat sering...",options:["Otomatiskan demi 'konsistensi'; mesin menilai setiap orang dengan cara yang sama tanpa terpengaruh perasaan maupun nilai","Otomatiskan lalu manusia sekadar menyetujui hasilnya tanpa memeriksa, demi proses cepat dan keputusan yang tampak diawasi","Tidak menyerahkannya ke model sama sekali — sebagian keputusan memang seharusnya tetap sepenuhnya di tangan manusia yang bertanggung jawab"],answer:2,explain:"Beberapa keputusan terlalu sarat nilai & konteks untuk dipercayakan pada pola statistik, betapapun 'akurat'.",hint:"Apakah semua keputusan penting sebaiknya diserahkan ke model?"},
{n:85,type:"order",micro:"Membangun sistem AI yang adil dari nol",q:"Urutkan langkah membangun sistem AI dengan keadilan sebagai pertimbangan sejak awal.",items:["Perjelas tujuan, siapa terdampak, & definisi keadilan (dengan masukan pihak terdampak)","Kumpulkan data yang representatif & label yang berpedoman jelas dari pelabel beragam","Latih, lalu evaluasi kinerja & jenis kesalahan PER KELOMPOK","Terapkan dengan tinjauan manusia untuk keputusan berdampak, transparansi, jalur banding, & pemantauan berkelanjutan"],answer:[0,1,2,3],explain:"Definisi & pihak terdampak → data & label yang adil → evaluasi per kelompok → penerapan dengan pengaman & pemantauan.",hint:"Kamu harus tahu 'adil untuk siapa, menurut apa' sebelum mengumpulkan data."},
{n:86,type:"mcq",micro:"Bias yang menguntungkan si pembuat",q:"Model rekomendasi toko daring sedikit lebih sering menampilkan produk milik toko itu sendiri dibanding penjual lain, meski relevansinya sama. Ini adalah bias yang...",options:["Menguntungkan pemilik sistem dengan mengorbankan kepentingan pengguna & penjual lain — konflik kepentingan yang perlu diungkap & diawasi","Wajar dan tidak bermasalah; toko berhak menampilkan produknya sendiri di urutan atas dan pengguna tidak dirugikan oleh urutan tampilan itu","Menguntungkan pengguna dan penjual lain sekaligus; produk toko sendiri adalah yang terbaik dan termurah bagi pembeli"],answer:0,explain:"Bias bisa dipasang secara halus demi keuntungan pemilik sistem. Transparansi & pengawasan luar penting.",hint:"Siapa yang diuntungkan kalau produk 'kebetulan' selalu muncul lebih dulu?"},
{n:87,type:"tf",micro:"Keadilan butuh suara yang terdampak",q:"Benar atau Salah: Keputusan tentang definisi keadilan & trade-off yang dapat diterima sebaiknya tidak dibuat hanya oleh pembuat teknis, melainkan melibatkan orang-orang yang akan terkena dampak sistem.",answer:true,explain:"Yang terdampak paling tahu bentuk kerugian yang nyata bagi mereka & apa yang terasa adil. Mengabaikan suara mereka menghasilkan sistem yang timpang.",hint:"Siapa yang paling berhak ikut menentukan apa yang 'adil' untuk sebuah keputusan tentang mereka?"},
{n:88,type:"mcq",micro:"Menimbang biaya audit vs risiko",q:"Untuk sistem AI yang menentukan akses ke layanan penting (kesehatan, pendidikan, keuangan), investasi besar dalam audit keadilan...",options:["Hanya untuk sistem kecil yang jarang dipakai, sedangkan sistem besar untuk layanan penting tidak perlu diaudit sedalam itu","Layak — biaya audit kecil dibanding kerugian sistematis & hilangnya kepercayaan bila sistem bias dipakai luas","Terlalu mahal dan tidak sepadan, jadi lewati saja auditnya dan perbaiki hanya kalau sudah ada orang yang mengeluh nanti"],answer:1,explain:"Semakin besar taruhannya bagi hidup orang, semakin sepadan investasi memastikan keadilan sebelum & selama penerapan.",hint:"Bandingkan biaya audit dengan biaya ribuan keputusan tidak adil yang tidak terdeteksi."},
{n:89,type:"mcq",micro:"Keadilan sebagai keunggulan, bukan beban",q:"Memandang keadilan sebagai bagian dari MUTU sistem (bukan hambatan) berarti...",options:["Keadilan mengorbankan kualitas sistem; sistem yang adil lebih lambat, lebih mahal, dan kurang dapat diandalkan","Keadilan hanya urusan hukum dan citra perusahaan, tanpa kaitan dengan mutu, kepercayaan, ataupun kinerja sistem","Sistem yang adil biasanya lebih andal, lebih dipercaya, lebih tahan gugatan, & melayani lebih banyak orang dengan baik"],answer:2,explain:"Sistem yang bekerja baik & adil untuk beragam orang adalah sistem yang lebih baik secara keseluruhan, bukan sekadar 'patuh aturan'.",hint:"Apakah sistem yang gagal untuk 30% penggunanya benar-benar sistem 'berkualitas tinggi'?"},
{n:90,type:"mcq",micro:"Menangani warisan keputusan bias",q:"Setelah menemukan bahwa sistem lama membuat keputusan bias selama bertahun-tahun, tanggung jawab yang etis mencakup...",options:["Bukan hanya memperbaiki sistem ke depan, tapi juga meninjau & memperbaiki dampak keputusan lalu yang merugikan bila memungkinkan","Cukup perbaiki sistem untuk masa depan dan lupakan keputusan yang sudah lalu; yang sudah terjadi dianggap tidak mungkin diubah lagi","Sembunyikan temuannya untuk menghindari kegaduhan; pengakuan dianggap hanya merusak nama baik lembaga itu di mata publik"],answer:0,explain:"Keadilan retrospektif — memperbaiki kerugian yang sudah terjadi — adalah bagian dari akuntabilitas, bukan hanya mencegah ke depan.",hint:"Kalau kamu tahu keputusan lama merugikan orang secara tidak adil, apa yang seharusnya dilakukan untuk mereka?"},
{n:91,type:"tf",micro:"Data & keadilan adalah keterampilan yang bisa dipelajari",q:"Benar atau Salah: Menilai bias data & keadilan sistem AI adalah bakat bawaan yang tidak bisa dilatih, jadi hanya sedikit orang yang mampu melakukannya.",answer:false,explain:"Kemampuan mengenali bias data & menilai keadilan sistem AI bisa dilatih siapa saja, dan semakin penting seiring AI dipakai untuk lebih banyak keputusan — literasi ini memberdayakan warga mempertanyakan & memperbaiki sistem yang memengaruhi hidup mereka.",hint:"Apakah kemampuan bertanya 'data ini mewakili siapa?' bisa dipelajari?"},
{n:92,type:"mcq",micro:"Pertanyaan inti untuk sistem AI apa pun",q:"Tiga pertanyaan keadilan yang selalu berguna diajukan tentang sistem AI:",options:["Apakah modelnya cepat? Apakah harganya murah? Apakah banyak orang sudah memakainya? Ketiganya menentukan apakah sistem itu adil","Data ini mewakili siapa (& tidak mewakili siapa)? Bagaimana kinerjanya per kelompok? Kalau salah, siapa yang paling dirugikan & bisakah mereka menggugat?","Berapa akurasinya? Siapa pembuatnya? Kapan dirilis? Tiga hal itu sudah cukup untuk mengetahui apakah sebuah sistem AI adil bagi semua"],answer:1,explain:"Keterwakilan data, kinerja per kelompok, & distribusi kerugian + hak banding adalah inti pemeriksaan keadilan.",hint:"Gabungkan: siapa di data + kinerja per kelompok + siapa yang dirugikan bila salah."},
{n:93,type:"mcq",micro:"Peran warga & pengguna",q:"Sebagai pengguna atau warga, kamu bisa mendorong keadilan AI dengan...",options:["Menerima keputusan AI tanpa bertanya, karena bertanya hanya akan memperlambat layanan dan tidak mengubah apa-apa di perusahaan itu","Menghindari teknologi yang memakai AI dalam jangka panjang, sebab itu cara yang tersedia agar kamu tidak terkena dampak ketidakadilannya","Melaporkan hasil yang tampak bias, menanyakan bagaimana keputusan dibuat, mendukung transparansi & audit, & tidak menganggap 'karena AI berarti objektif'"],answer:2,explain:"Tekanan dari pengguna & publik yang melek AI adalah pendorong penting akuntabilitas & perbaikan.",hint:"Apa yang bisa kamu lakukan saat melihat sistem AI memperlakukan orang secara tidak adil?"},
{n:94,type:"open",micro:"Audit keadilan mini",q:"Pilih satu sistem berbasis data/AI yang kamu tahu (rekomendasi, filter, penilaian otomatis, pengenalan, dll.). Lakukan 'audit keadilan mini' tertulis: (1) apa yang diputuskan & siapa terdampak, (2) dari data seperti apa ia mungkin belajar & minimal 2 bias yang mungkin (sebutkan jenisnya), (3) bagaimana kesalahannya bisa merugikan kelompok berbeda secara tidak setara, (4) apa yang akan kamu ukur untuk mengeceknya, (5) 2 perbaikan yang mungkin, (6) apakah keputusan ini sebaiknya diotomatiskan sepenuhnya, dibantu AI dengan tinjauan manusia, atau tetap sepenuhnya manusia — dan mengapa.",explain:"Kapstone menuntut penerapan semua konsep: prediksi–terdampak, sumber data & jenis bias (historis/pengukuran/keterwakilan), distribusi kerugian yang tidak setara, rencana pengukuran per kelompok, perbaikan konkret, & argumen tentang tingkat otomatisasi yang tepat.",hint:"Untuk bagian (2), beri nama jenis biasnya (historis / pengukuran / keterwakilan / proksi) — jangan hanya bilang 'bias'.",sample:"Audit yang baik mengisi keenam bagian dengan spesifik. Contoh: sistem penyaring CV otomatis untuk lowongan magang. (1) Memutuskan CV mana yang lolos ke tahap wawancara; terdampak: semua pelamar, terutama dari sekolah/latar yang kurang 'sesuai pola' pelamar yang diterima sebelumnya. (2) Belajar dari data pelamar & karyawan yang diterima di masa lalu. Bias historis (kalau dulu jarang menerima dari sekolah non-favorit, model belajar itu); bias pengukuran (menilai 'kualitas' dari kata kunci/nama institusi, bukan kemampuan nyata); bias keterwakilan (pelamar dari kelompok tertentu sedikit di data). (3) Positif palsu rendah untuk kelompok dominan (mereka lolos meski biasa saja); negatif palsu tinggi untuk kelompok kurang terwakili (mereka ditolak meski mampu) → kesempatan hilang secara sistematis. (4) Ukur: tingkat lolos & jenis kesalahan per kelompok (sekolah asal, jenis kelamin, dll.) dibanding penilaian manusia terlatih pada sampel yang sama. (5) Perbaikan: latih ulang dengan data yang diseimbangkan & label berdasarkan tes keterampilan nyata (bukan sekadar riwayat); hapus/uji fitur proksi seperti nama institusi. (6) Sebaiknya AI hanya membantu mengurutkan/menandai, dengan perekrut manusia meninjau — karena menilai potensi orang sarat konteks & kesalahan berdampak besar pada peluang hidup; pelamar juga sebaiknya bisa tahu & menggugat."},
{n:95,type:"mcq",micro:"Keadilan lintas budaya",q:"Sebuah model yang dianggap 'adil' di satu negara diterapkan di negara lain. Sikap yang tepat:",options:["Periksa ulang: kelompok relevan, norma keadilan, & konteks sosial bisa berbeda; keadilan tidak otomatis 'terbawa' lintas konteks","Anggap sudah adil di negara baru; sistem yang adil di satu negara dianggap juga adil di negara dengan budaya dan hukum yang berbeda","Tolak sistem dari luar negeri; teknologi asing dianggap tidak cocok dan tidak mungkin disesuaikan dengan keadaan setempat"],answer:0,explain:"Definisi kelompok, kesenjangan yang relevan, & apa yang dianggap adil bervariasi antar masyarakat. Perlu evaluasi ulang di tiap konteks.",hint:"Apakah 'adil' berarti hal yang sama persis di setiap masyarakat?"},
{n:96,type:"mcq",micro:"Menyeimbangkan manfaat AI & risiko keadilan",q:"Pandangan paling matang tentang AI & keadilan:",options:["AI bersifat netral dan objektif, jadi tidak perlu dikhawatirkan dan tidak butuh pemeriksaan keadilan; manfaatnya dinikmati seluruh lapisan masyarakat sama rata dan adil","AI bisa sangat bermanfaat DAN berisiko memperkuat ketidakadilan; keduanya benar, jadi manfaatnya dikejar dengan pemeriksaan keadilan yang serius & berkelanjutan","AI memperburuk keadilan dalam semua keadaan, jadi sebaiknya tidak dipakai untuk keperluan di masyarakat, walau ada pemeriksaan yang serius dan berkelanjutan"],answer:1,explain:"Menolak AI sepenuhnya atau mempercayainya buta sama-sama keliru. Pemakaian yang bertanggung jawab mengejar manfaat sambil menjaga keadilan.",hint:"Bisakah sesuatu berpotensi sangat berguna DAN berpotensi merugikan bila tidak dijaga?"},
{n:97,type:"tf",micro:"Transparansi memungkinkan koreksi",q:"Benar atau Salah: Sistem AI yang cara kerjanya & datanya lebih transparan lebih mudah diperiksa, digugat, & diperbaiki daripada 'kotak hitam' yang tertutup.",answer:true,explain:"Transparansi adalah prasyarat akuntabilitas. Yang tidak bisa diperiksa tidak bisa diperbaiki oleh pihak luar.",hint:"Bisakah kamu memperbaiki sesuatu yang tidak boleh kamu lihat isinya?"},
{n:98,type:"mcq",micro:"Menutup: data, bias, & keadilan",q:"Rangkuman paling tepat:",options:["Data bersifat netral dan model objektif, jadi keadilan terjadi dengan sendirinya tanpa perlu definisi, pengukuran per kelompok, pemantauan, atau tinjauan manusia, dan pihak terdampak tak perlu dimintai masukan atau diberi transparansi","Bias mustahil diukur, jadi tak usah dicoba; cukup percaya pada niat baik pembuat model dan berharap tak ada kelompok yang dirugikan, tanpa perbaikan data, transparansi, tinjauan manusia, atau pemantauan setelah peluncuran","Data mencerminkan dunia yang timpang & pilihan pengumpulnya, jadi model bisa mewarisi & memperkuat bias; keadilan menuntut definisi jelas, pengukuran per kelompok, perbaikan data, transparansi, tinjauan manusia, & pemantauan"],answer:2,explain:"Inti: bias masuk lewat data & pilihan manusia di setiap tahap; keadilan adalah proses aktif & berkelanjutan yang melibatkan yang terdampak.",hint:"Gabungkan: data timpang → model bias → keadilan = definisi + ukur per kelompok + perbaiki + transparan + pantau."},
{n:99,type:"mcq",micro:"Prioritas saat sumber daya terbatas",q:"Sebuah organisasi kecil tidak bisa mengaudit semua sistemnya secara mendalam. Prioritas yang masuk akal:",options:["Utamakan audit keadilan pada sistem yang keputusannya paling berdampak pada hak, kesempatan, atau keselamatan orang","Audit yang paling mudah dan murah dilakukan lebih dulu, tanpa memandang seberapa besar dampaknya bagi orang","Tidak mengaudit sistem mana pun sebelum ada keluhan resmi dari pengguna yang merasa dirugikan olehnya"],answer:0,explain:"Sesuaikan kedalaman pemeriksaan dengan taruhannya. Sistem berdampak tinggi (akses layanan, seleksi, keselamatan) didahulukan.",hint:"Sistem mana yang kalau bias akan paling menyakiti orang?"},
{n:100,type:"open",micro:"Kapstone: kebijakan keadilan AI untuk sebuah lembaga",q:"Bayangkan kamu membantu sekolah/organisasi menyusun 'kebijakan keadilan AI' singkat. Tuliskan minimal 6 aturan/komitmen konkret yang mencakup: kapan AI boleh dipakai untuk keputusan tentang orang; syarat data & pengujian sebelum dipakai; peran manusia; hak orang yang terdampak; pemantauan; & apa yang terjadi bila bias ditemukan. Untuk tiap aturan, jelaskan singkat alasannya.",explain:"Kapstone menghasilkan artefak kebijakan yang mengoperasionalkan semua prinsip: batas otomatisasi, uji per kelompok pra-penerapan, transparansi & tinjauan, hak diberi tahu & banding, pemantauan berkala, respons terhadap bias (termasuk retrospektif), & perlindungan privasi data audit.",hint:"Tiap aturan harus konkret ('diuji per kelompok sebelum dipakai') dan punya alasan ('agar ketimpangan tersembunyi ketahuan').",sample:"Contoh kebijakan: (1) AI hanya boleh MEMBANTU, tidak menentukan sendiri, keputusan yang memengaruhi hak/kesempatan seseorang (nilai, seleksi, sanksi) — karena kesalahan berdampak besar & menilai orang sarat konteks. (2) Sebelum dipakai, sistem harus diuji kinerjanya secara terpisah untuk kelompok yang relevan (jenis kelamin, latar ekonomi, kebutuhan khusus, kelas) dengan data yang mewakili siswa kita — agar ketimpangan tersembunyi ketahuan. (3) Data latih & kriteria harus didokumentasikan & bisa ditinjau oleh komite yang mencakup guru, orang tua, & (bila sesuai) siswa — agar tidak ada 'kotak hitam'. (4) Setiap orang yang terkena keputusan berbantuan AI berhak diberi tahu, mengetahui faktor utamanya, & meminta peninjauan oleh manusia — sebagai pengaman terhadap kesalahan. (5) Kinerja & keadilan sistem ditinjau tiap semester, dengan mengumpulkan umpan balik dari yang terdampak — karena data & kebutuhan berubah. (6) Bila bias serius ditemukan, pemakaian dihentikan untuk keputusan berdampak sampai diperbaiki & diuji ulang, & keputusan lalu yang merugikan ditinjau kembali — karena akuntabilitas mencakup memperbaiki kerugian yang sudah terjadi. (7) Data kelompok sensitif yang dikumpulkan untuk audit hanya dipakai untuk itu, disimpan aman, & dihapus sesudahnya — menyeimbangkan pemeriksaan keadilan dengan privasi."},
];
